import torch


def run(size, dtype):
    dt = getattr(torch, dtype)
    return torch.rand(size, dtype=dt)


def valid(ref_outputs, sol_outputs, inputs, ctx):
    sol = sol_outputs[0]
    size = inputs[0]
    if list(sol.shape) != list(size):
        return {
            "passed": False,
            "message": f"shape {tuple(sol.shape)} vs {tuple(size)}",
            "metrics": {},
        }
    sol_f = sol.detach().to("cpu").to(torch.float64)
    ge = bool((sol_f >= 0.0).all().item())
    le = bool((sol_f <= 1.0).all().item())
    return {"passed": bool(ge and le), "message": "", "metrics": {}}
